def seed_ai_models(apps, schema_editor):
    AIModelName = apps.get_model('myapp', 'AIModelName')
    if not AIModelName.objects.exists():
        for order, (name, tagline) in enumerate(_SEED_MODELS):
            AIModelName.objects.create(name=name, tagline=tagline, order=order)

    Product = apps.get_model('myapp', 'Product')
    for product in Product.objects.filter(slug__in=_VIDHYORA_SLUGS):
        if _OLD_DESC_BLOCK in product.description:
            product.description = product.description.replace(_OLD_DESC_BLOCK, '{{AI_MODELS}}')
        if _OLD_SPECS_LINE in product.specs:
            product.specs = product.specs.replace(_OLD_SPECS_LINE, 'Models: {{AI_MODELS}}')
        if _OLD_TAGS_BLOCK in product.tags:
            product.tags = product.tags.replace(_OLD_TAGS_BLOCK, '{{AI_MODELS}}')
        product.save(update_fields=['description', 'specs', 'tags'])


